+                <div class="d-flex justify-content-center py-5">
+                    <div class="spinner-border text-primary" role="status">
+                        <span class="visually-hidden">Loading...</span>
+                    </div>
+                </div>
+            }
+            else if (_products.Count == 0)
+            {
+                <div class="alert alert-info text-center" role="alert">
+                    No products found matching your criteria.
+                </div>
+            }
+            else
+            {
+                <ProductGrid Products="_products"
+                             OnProductSelected="HandleProductSelected"
+                             OnAddToCart="HandleAddToCart" />
+
+                @if (_totalPages > 1)
+                {
+                    <div class="mt-4">
+                        <CatalogPagination CurrentPage="_currentPage"
+                                           TotalPages="_totalPages"
+                                           OnPageChanged="HandlePageChanged" />
+                    </div>
+                }
+            }
+        </div>
+    </div>
+}
+
+@code {
+    private List<Product> _products = [];
+    private List<string> _categories = [];
+    private ProductFilter _filter = new(null, null, null, false);
+    private string _sortBy = "price_asc";
+    private int _currentPage = 1;
+    private int _pageSize = 12;
+    private int _totalCount;
+    private int _totalPages;
+    private bool _loading = true;
+    private string? _error;
+
+    [Parameter]
+    public EventCallback<int> OnProductSelected { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _categories = await ProductService.GetCategoriesAsync();
+            await LoadProducts();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+            _loading = false;
+        }
+    }
+
+    private async Task LoadProducts()
+    {
+        _loading = true;
+        StateHasChanged();
+
+        try
+        {
+            var result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
+            _products = result.Items;
+            _totalCount = result.TotalCount;
+            _totalPages = (int)Math.Ceiling((double)result.TotalCount / _pageSize);
+            _error = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task HandleFilterApplied(ProductFilter filter)
+    {
+        _filter = filter;
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleFilterCleared()
+    {
+        _filter = new ProductFilter(null, null, null, false);
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleSortChanged(string sortBy)
+    {
+        _sortBy = sortBy;
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        _currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task HandleProductSelected(int productId)
+    {
+        await OnProductSelected.InvokeAsync(productId);
+    }
+
+    private Task HandleAddToCart(int productId)
+    {
+        // Placeholder for add-to-cart logic
+        return Task.CompletedTask;
+    }
+}
+

